namespace MC_BE.Features.Courses.DTOs;

/// <summary>
/// Read-only material data returned to an authorized course viewer.
/// Video URLs are short-lived presigned URLs generated by the service.
/// </summary>
public sealed class CourseMaterialReadDto
{
    public int MaterialId { get; init; }
    public int? LessonId { get; init; }
    public string Title { get; init; } = string.Empty;
    public string? FileUrl { get; init; }
    public string? MaterialType { get; init; }
}
